struct FEN{
	int fen[500005];

	FEN(){
		memset(fen,0,sizeof(fen));
	}

	void upd(int i,int j){
		while (i<500005){
			fen[i]+=j;
			i+=i&-i;
		}
	}

	int query(int i){
		int res=0;
		while (i){
			res+=fen[i];
			i-=i&-i;
		}
		return res;
	}
} fval,fidx;

struct dat{
	struct node{
		int s,e,m;
		ii val;
		int lazy=0;
		node *l,*r;

		node (int _s,int _e){
			s=_s,e=_e,m=s+e>>1;
			val={1e9,s};

			if (s!=e){
				l=new node(s,m);
				r=new node(m+1,e);
			}
		}

		void propo(){
			if (lazy){
				val.fi+=lazy;
				if (s!=e){
					l->lazy+=lazy;
					r->lazy+=lazy;
				}
				lazy=0;
			}
		}

		void update(int i,int j,int k){
			if (s==i && e==j) lazy+=k;
			else{
				if (j<=m) l->update(i,j,k);
				else if (m<i) r->update(i,j,k);
				else l->update(i,m,k),r->update(m+1,j,k);

				l->propo(),r->propo();
				val=min(l->val,r->val);
			}
		}

		void set(int i,int k){
			propo();
			if (s==e) val.fi=k;
			else{
				if (i<=m) l->set(i,k);
				else r->set(i,k);

				l->propo(),r->propo();
				val=min(l->val,r->val);
			}
		}
	} *root=new node(0,500005);

	struct node2{
		int s,e,m;
		int val=-1e9;
		node2 *l,*r;

		node2 (int _s,int _e){
			s=_s,e=_e,m=s+e>>1;

			if (s!=e){
				l=new node2(s,m);
				r=new node2(m+1,e);
			}
		}

		void update(int i,int k){
			if (s==e) val=k;
			else{
				if (i<=m) l->update(i,k);
				else r->update(i,k);
				val=max(l->val,r->val);
			}
		}

		ii query(int i,int key){ //find key<=val where i<=s
			if (e<i || val<key) return {-1,-1};
			if (s==e) return {s,val};
			else{
				auto temp=l->query(i,key);
				if (temp!=ii(-1,-1)) return temp;
				else return r->query(i,key);
			}
		}
	} *root2=new node2(0,500005);

	set<ii> s={ {500005,500005} };

	//root stores the values of each pair
	//root2 stores the left endpoint of each pair to add non-overlapping ranges
	//s stores the pairs are still alive so its easy to do searches

	dat *d; //we also store the other guy
	bool orien; //false for i->arr[i]

	int pp[500005];

	void push(int i,int j){
		pp[j]=i;
		root2->update(j,i);
	}

	void add(int i,int j){
		root2->update(j,-1e9);
		s.insert({i,j});

		int val;
		if (!orien) val=fval.query(j)-fidx.query(i);
		else val=fidx.query(j)-fval.query(i);

		root->set(j,val);
	}

	void del(int j){
		ii curr={-1,-1};
		int lim=500005;

		if (j!=-1){
			int i=pp[j];

			auto it=d->s.ub({j,1e9});
			d->root->update(i,(*it).se-1,-1);

			if (!orien) fidx.upd(i,-1),fval.upd(j,-1);
			else fval.upd(i,-1),fidx.upd(j,-1);

			it=s.find({i,j});
			if (it!=s.begin()) curr=*prev(it);
			lim=(*next(it)).se;
			s.erase(it);
			root->set(j,1e9);
			root2->update(j,-1e9);
		}

		while (true){
			auto temp=root2->query(curr.se,curr.fi);
			swap(temp.fi,temp.se);
			if (temp==ii(-1,-1) || lim<=temp.se) break;

			add(temp.fi,temp.se);
			curr=temp;
		}
	}
} *l=new dat(),*r=new dat();

int n;

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	cin.exceptions(ios::badbit | ios::failbit);

	//cyclic mapping to each other
	l->d=r;
	r->d=l;

	r->orien=true;

	cin>>n;
	rep(x,1,n+1){
		int y;
		cin>>y;

		if (x<=y) l->push(x,y);
		else r->push(y,x);
	}

	rep(x,1,n+1) fidx.upd(x,1),fval.upd(x,1);
	l->del(-1);
	r->del(-1);

	int ans=0;

	rep(x,0,n){
		if (l->root->val.fi<=r->root->val.fi){
			ans=max(ans,l->root->val.fi);
			l->del(l->root->val.se);
		}
		else{
			ans=max(ans,r->root->val.fi);
			r->del(r->root->val.se);
		}
	}

	cout<<ans<<endl;
}
